      "ho_id": "HO1",
      "meaningful_trajectory_impact": false,
      "triggered": false
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00034",
          "explanation": "The family raised ambiguity about bone loss versus osteoporosis and whether lack of a T-score changed surgical safety.",
          "quote": "骨量减少"
        },
        {
          "event_id": "lite_evt_00040",
          "explanation": "The doctor actively distinguished bone loss from severe osteoporosis.",
          "quote": "不等于“重度骨质疏松”"
        }
      ],
      "completion": "partial",
      "explanation": "The doctor recognized a false-positive/false-negative boundary and corrected that bone loss is not automatically severe osteoporosis. It was not completed because the same response overreached by saying DXA was mandatory that day and did not reliably integrate final pre-op evaluation boundaries.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": false,
      "triggered": true
    },
    {
      "active_model_action": false,
      "citations": [],
      "completion": "not_triggered",
      "explanation": "A concrete family conflict between rushing ambulation and prolonged bedrest did not visibly surface in the retained dialogue, and the doctor did not actively discover or repair such a conflict beyond ordinary fall/rehab advice.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": false,
      "triggered": false
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00062",
          "explanation": "The doctor attempted bounded closure by compressing the immediate overnight-to-morning tasks.",
          "quote": "这四条就够"
        },
        {
          "event_id": "lite_evt_00083",
          "explanation": "The doctor attempted to narrow future tasks to wound, imaging, and follow-up surveillance.",
          "quote": "以后要盯的是"
        }
      ],
      "completion": "partial",
      "explanation": "The doctor attempted a bounded current-stage closure, but it was not safely complete because core responsibility-chain gaps remained and the family’s final clarification about formal follow-up was unanswered.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": false,
      "triggered": true
    }
  ],
